import csv, collections
rows=list(csv.DictReader(open('ae_death_age_gender.csv')))
h=list(rows[0].keys())
print('HDR',h,'N',len(rows))
low={k.lower():k for k in h}
def g(names):
    for n in names:
        if n in low: return low[n]
    return None
Y=g(['year']); A=g(['actual']); E=g(['expected'])
SEG=[c for c in h if c not in (Y,A,E) and c.lower() not in ('ae','a/e','a/e ratio')]
print('Y,A,E,SEG',Y,A,E,SEG)
if Y and A and E:
    seg_year=collections.defaultdict(lambda:[0.0,0.0])
    bad=0
    for r in rows:
        try:
            a=float(r[A]); e=float(r[E]); y=int(float(r[Y]))
        except Exception:
            bad+=1; continue
        k=(y,)+tuple(r[c] for c in SEG)
        seg_year[k][0]+=a; seg_year[k][1]+=e
    print('bad',bad)
    byy=collections.defaultdict(lambda:[0.0,0.0])
    for (y,*_s),(a,e) in seg_year.items():
        byy[y][0]+=a; byy[y][1]+=e
    for y in sorted(byy):
        a,e=byy[y]; print('YEAR',y,'AE',round(a/e,3))
    s17=collections.defaultdict(lambda:[0.0,0.0]); s2=collections.defaultdict(lambda:[0.0,0.0])
    for (y,*s),(a,e) in seg_year.items():
        tgt=s17 if y in (2016,2017) else s2
        tgt[s][0]+=a; tgt[s][1]+=e
    rows2=[]
    for s in s17:
        a1,e1=s17[s]; a2,e2=s2.get(s,(0.0,0.0))
        ae1=a1/e1 if e1 else None; ae2=a2/e2 if e2 else None
        rows2.append((a1-e1, s, round(ae1,3) if ae1 is not None else None, round(ae2,3) if ae2 is not None else None, round(e1), round(e2)))
    rows2.sort(reverse=True)
    for r in rows2[:15]: print('SEG',r)
    print('nseg',len(rows2))
